1	import { build } from './build';
2	
3	export interface CliArgs {
4	  command: string;
5	  contentDir: string;
6	  outputDir: string;
7	  templatesDir?: string;
8	}
9	
10	const DEFAULT_CONTENT_DIR = './content';
11	const DEFAULT_OUTPUT_DIR = './dist';
12	
13	export function parseArgs(argv: string[]): CliArgs {
14	  const [command = 'build', ...rest] = argv;
15	  let contentDir = DEFAULT_CONTENT_DIR;
16	  let outputDir = DEFAULT_OUTPUT_DIR;
17	  let templatesDir: string | undefined;
18	
19	  for (let i = 0; i < rest.length; i++) {
20	    const arg = rest[i];
21	    if (arg === '--content') {
22	      const value = rest[i + 1];
23	      if (!value) throw new Error('--content requires a directory argument');
24	      contentDir = value;
25	      i++;
26	    } else if (arg === '--output') {
27	      const value = rest[i + 1];
28	      if (!value) throw new Error('--output requires a directory argument');
29	      outputDir = value;
30	      i++;
31	    } else if (arg === '--templates') {
32	      const value = rest[i + 1];
33	      if (!value) throw new Error('--templates requires a directory argument');
34	      templatesDir = value;
35	      i++;
36	    } else {
37	      throw new Error(`Unknown argument: ${arg}`);
38	    }
39	  }
40	
41	  return { command, contentDir, outputDir, ...(templatesDir !== undefined ? { templatesDir } : {}) };
42	}
43	
44	export function run(argv: string[]): void {
45	  const args = parseArgs(argv);
46	
47	  if (args.command !== 'build') {
48	    throw new Error(`Unknown command: ${args.command}. Supported commands: build`);
49	  }
50	
51	  const result = build({ contentDir: args.contentDir, outputDir: args.outputDir, templatesDir: args.templatesDir });
52	  // eslint-disable-next-line no-console
53	  console.log(`Built ${result.pages.length} page(s) from ${args.contentDir} to ${args.outputDir}`);
54	}
55	
56	export function main(): void {
57	  try {
58	    run(process.argv.slice(2));
59	  } catch (error) {
60	    const message = error instanceof Error ? error.message : String(error);
61	    // eslint-disable-next-line no-console
62	    console.error(`ssg: ${message}`);
63	    process.exitCode = 1;
64	  }
65	}
66	
67	if (require.main === module) {
68	  main();
69	}
