1	import * as path from 'path';
2	import { Page } from './types';
3	import { escapeHtml, TemplateEngine } from './templateEngine';
4	
5	export { escapeHtml };
6	
7	const DEFAULT_TEMPLATES_DIR = './templates';
8	
9	const engineCache = new Map<string, TemplateEngine>();
10	
11	function getEngine(templatesDir: string): TemplateEngine {
12	  const resolved = path.resolve(templatesDir);
13	  let engine = engineCache.get(resolved);
14	  if (!engine) {
15	    engine = new TemplateEngine(templatesDir);
16	    engineCache.set(resolved, engine);
17	  }
18	  return engine;
19	}
20	
21	function basePathFor(slug: string): string {
22	  return '../'.repeat(slug.split('/').length - 1);
23	}
24	
25	function metaHtml(page: Page): string {
26	  const parts: string[] = [];
27	  if (page.frontmatter.date) {
28	    parts.push(`<time datetime="${escapeHtml(page.frontmatter.date)}">${escapeHtml(page.frontmatter.date)}</time>`);
29	  }
30	  if (page.frontmatter.tags.length > 0) {
31	    const tags = page.frontmatter.tags.map((tag) => `<span class="tag">${escapeHtml(tag)}</span>`).join(' ');
32	    parts.push(`<span class="tags">${tags}</span>`);
33	  }
34	  return parts.length > 0 ? `<p class="meta">${parts.join(' &middot; ')}</p>` : '';
35	}
36	
37	export interface RenderPageOptions {
38	  /** Directory holding page/index templates, layouts/, and partials/. Defaults to './templates'. */
39	  templatesDir?: string;
40	  /** Site-wide title shown in the header/footer partials. Defaults to the page's own title. */
41	  siteTitle?: string;
42	}
43	
44	export interface RenderIndexOptions {
45	  /** Directory holding page/index templates, layouts/, and partials/. Defaults to './templates'. */
46	  templatesDir?: string;
47	}
48	
49	/** Renders a single content page using its frontmatter-selected template and layout (or the defaults). */
50	export function renderPageHtml(page: Page, options: RenderPageOptions = {}): string {
51	  const engine = getEngine(options.templatesDir ?? DEFAULT_TEMPLATES_DIR);
52	  const basePath = basePathFor(page.slug);
53	  const title = escapeHtml(page.frontmatter.title);
54	  const siteTitle = escapeHtml(options.siteTitle ?? page.frontmatter.title);
55	
56	  return engine.render(
57	    page.frontmatter.template ?? 'page',
58	    page.frontmatter.layout ?? 'default',
59	    { title, meta: metaHtml(page), content: page.contentHtml, basePath },
60	    { title, siteTitle, basePath }
61	  );
62	}
63	
64	/** Renders the site index listing using the 'index' template wrapped in the default layout. */
65	export function renderIndexHtml(pages: Page[], siteTitle: string, options: RenderIndexOptions = {}): string {
66	  const engine = getEngine(options.templatesDir ?? DEFAULT_TEMPLATES_DIR);
67	  const escapedSiteTitle = escapeHtml(siteTitle);
68	  const items = pages.map((page) => ({
69	    title: escapeHtml(page.frontmatter.title),
70	    href: escapeHtml(`${page.slug}.html`),
71	    meta: metaHtml(page),
72	  }));
73	
74	  return engine.render(
75	    'index',
76	    'default',
77	    { pages: items, siteTitle: escapedSiteTitle },
78	    { title: escapedSiteTitle, siteTitle: escapedSiteTitle, basePath: '' }
79	  );
80	}
